/* ═══════════════════════════════════════════════════════════════
   EquityLens — Company History Engine
   Dynamic sector-playbook generator for tickers not in the
   hardcoded institutional archive (stockHistory.ts).

   Uses Yahoo Finance data + sector-specific event playbooks to
   build a realistic company evolution timeline for any NSE/BSE stock.
═══════════════════════════════════════════════════════════════ */

import type { StockHistoryProfile, TimelineEvent, NarrativeEra, SentimentDataPoint, EventSentiment, EventCategory } from "@/lib/stockHistory";
import type { NewsItem } from "./newsAggregator";

function clamp(v: number, lo = 0, hi = 100) { return Math.max(lo, Math.min(hi, v)); }
function fmtInr(n: number) { return `₹${n.toFixed(0)}`; }

/* ── Sector detection ───────────────────────────────────────── */
export function detectSectorCategory(quote: any, ticker: string): string {
  const sec = (quote?.sector ?? "").toLowerCase();
  const t   = ticker.toUpperCase();

  if (sec.includes("technology") || sec.includes("information")) return "IT_SERVICES";
  if (sec.includes("financial") && /SBI|BOB|PNB|CANBK|UNION|BANKINDIA|BANKBARODA|CENTRALBANK/.test(t)) return "PSU_BANKING";
  if (sec.includes("financial services") && !sec.includes("bank")) return "NBFC_FINANCE";
  if (sec.includes("financial") || sec.includes("bank")) return "PRIVATE_BANKING";
  if (sec.includes("aerospace") || /BEL|BEML|COCHIN|GRSE|MIDHANI|MAZAGON|BDL|DCAL/.test(t)) return "DEFENSE_PSU";
  if (sec.includes("energy") || sec.includes("oil") || sec.includes("gas")) return "ENERGY_OIL";
  if (sec.includes("healthcare") || sec.includes("pharma") || sec.includes("biotech")) return "PHARMA";
  if (sec.includes("consumer cyclical") || sec.includes("automobile") || sec.includes("auto")) return "AUTO";
  if (sec.includes("consumer defensive") || sec.includes("consumer staples")) return "FMCG";
  if (sec.includes("basic materials") || sec.includes("metals") || sec.includes("mining")) return "METALS";
  if (sec.includes("utilities") || /NTPC|POWERGRID|IRCON|RVNL|IRCTC|PGCIL/.test(t)) return "INFRA_POWER";
  if (sec.includes("communication") || sec.includes("telecom")) return "TELECOM";
  if (sec.includes("real estate") || sec.includes("realty")) return "REAL_ESTATE";
  return "DIVERSIFIED";
}

/* ── News → latestDevelopments ──────────────────────────────── */
function newsToDevs(
  news: NewsItem[],
  company: string,
): StockHistoryProfile["latestDevelopments"] {
  return (news as any[]).slice(0, 4).map((n: any) => ({
    headline: n.title,
    aiRead: n.sentiment === "positive"
      ? `Institutional read: Constructive development for ${company}. Smart money views this as a forward-thesis confirmation — expect accumulation on any near-term dips. The signal-to-noise ratio here is high.`
      : n.sentiment === "negative"
      ? `Institutional read: Warrants monitoring. ${company}'s institutions will assess whether this is transient or structural before adjusting portfolio weights. Risk-adjusted entry zones shift modestly lower.`
      : `Institutional read: Neutral — secondary implications for margin profile or competitive positioning may emerge over the following 1-2 quarters. No immediate thesis revision required.`,
    date:      new Date((n as any).publishedAt ?? Date.now()).toLocaleDateString("en-IN", { month: "short", year: "numeric" }),
    sentiment: (n.sentiment === "positive" ? "BULLISH" : n.sentiment === "negative" ? "BEARISH" : "NEUTRAL") as EventSentiment,
  }));
}

/* ══════════════════════════════════════════════════════════════
   SECTOR PLAYBOOKS
   Each function returns events + eras + chart + texts
   parameterized with the specific company.
══════════════════════════════════════════════════════════════ */

type PlaybookResult = Pick<StockHistoryProfile,
  "timeline" | "narrativeEvolution" | "sentimentChart" |
  "smartMoneyAnalysis" | "macroConnections" | "oneLiner" | "keyRisks" | "currentSentiment" | "currentTrend"
>;

interface PlaybookParams {
  ticker: string; company: string; price: number | null;
  change1d: number | null; hi52: number | null; lo52: number | null;
  pe: number | null; roe: number | null; de: number | null;
  revGrowth: number | null; exchange: string; sector: string;
}

