/* ══════════════════════════════════════════════════════════════
   MAIN EXPORT — buildCompanyHistory
══════════════════════════════════════════════════════════════ */

export function buildCompanyHistory(
  ticker:  string,
  quote:   any,
  summary: any,
  news:    NewsItem[],
): StockHistoryProfile {
  const T       = ticker.toUpperCase();
  const company = quote?.longName ?? quote?.shortName ?? T;
  const sector  = quote?.sector ?? summary?.assetProfile?.sector ?? "Indian Equity";
  const exchange = quote?.exchange ?? "NSE";
  const cap     = (() => {
    const mc = quote?.marketCap;
    if (!mc) return "Unknown";
    if (mc > 2e12) return "Mega Cap";
    if (mc > 5e11) return "Large Cap";
    if (mc > 1e11) return "Mid Cap";
    return "Small Cap";
  })();

  const params: PlaybookParams = {
    ticker: T, company, price: quote?.regularMarketPrice ?? null,
    change1d: quote?.regularMarketChangePercent ?? null,
    hi52: quote?.fiftyTwoWeekHigh ?? null, lo52: quote?.fiftyTwoWeekLow ?? null,
    pe: quote?.trailingPE ?? null,
    roe: summary?.financialData?.returnOnEquity ?? null,
    de: summary?.financialData?.debtToEquity ?? null,
    revGrowth: summary?.financialData?.revenueGrowth ?? null,
    exchange, sector,
  };

  const cat = detectSectorCategory(quote, T);

  const playbook: PlaybookResult = (() => {
    switch (cat) {
      case "IT_SERVICES":      return itServicesPlaybook(params);
      case "PSU_BANKING":      return psuBankingPlaybook(params);
      case "PRIVATE_BANKING":  return privateBankingPlaybook(params);
      case "DEFENSE_PSU":      return defensePsuPlaybook(params);
      case "ENERGY_OIL":       return infraPowerPlaybook(params); // closest match; energy separate TODO
      case "PHARMA":           return pharmaPlaybook(params);
      case "AUTO":             return autoPlaybook(params);
      case "FMCG":             return fmcgPlaybook(params);
      case "METALS":           return metalsPlaybook(params);
      case "INFRA_POWER":      return infraPowerPlaybook(params);
      case "NBFC_FINANCE":     return nbfcFinancePlaybook(params);
      case "TELECOM":          return telecomPlaybook(params);
      case "REAL_ESTATE":      return realEstatePlaybook(params);
      default:                 return diversifiedPlaybook(params);
    }
  })();

  const liveDevelopments = newsToDevs(news, company);
  const latestDevelopments = liveDevelopments.length > 0
    ? liveDevelopments
    : [{ headline: `${company} — Live news unavailable`, aiRead: "Connect to live news aggregator for latest developments.", date: "Current", sentiment: "NEUTRAL" as EventSentiment }];

  return {
    ticker: T,
    name:   company,
    sector,
    cap,
    exchange,
    currentTrend:     playbook.currentTrend,
    currentSentiment: playbook.currentSentiment,
    oneLiner:         playbook.oneLiner,
    timeline:         playbook.timeline,
    narrativeEvolution: playbook.narrativeEvolution,
    sentimentChart:     playbook.sentimentChart,
    smartMoneyAnalysis: playbook.smartMoneyAnalysis,
    macroConnections:   playbook.macroConnections,
    latestDevelopments,
    keyRisks:           playbook.keyRisks,
  };
}
